/*
 * Freally Takelight — the roster page: every artist and genre with a vocal
 * chain, era by era, A–Z.
 * © 2026 Mike Weaver — All Rights Reserved.
 *
 * ⛔⛔ THE ONLY SITE-SPECIFIC SCRIPT ON THIS SITE, and it is the roster's alone
 * (site.json `scripts.roster`), ported from Freally MIDI Master's. Everything
 * else — the shell, the languages, the reveals — is the site kit's
 * `kit/kit.js`, the same on every Freally site.
 *
 * ⛔ `roster.json` is GENERATED by `tlc build` from the compiled chains the
 * plugin ships (npm run chains:build), and `tlc build --check` fails when it
 * drifts; never hand-maintain it. It holds names, eras, roles and genres only.
 *
 * ⚠ Every word this script writes is on the page already, in a hidden
 * `[data-roster-word]` element the kit translates like any other — so this
 * reads the words back in whatever language is showing, and redraws when the
 * reader picks another. No string here is shown to a reader.
 */

(function () {
  'use strict';

  var CHUNK = 250;

  function word(name) {
    var node = document.querySelector('[data-roster-word="' + name + '"]');
    return node === null ? '' : node.textContent;
  }

  function fillIn(template, values) {
    return template.replace(/\{(\w+)\}/g, function (whole, name) {
      return name in values ? values[name] : whole;
    });
  }

  function number(value) {
    try {
      return value.toLocaleString(document.documentElement.lang || 'en');
    } catch (error) {
      return String(value);
    }
  }

  /**
   * An era as the page's language says it, from the form `tlc build` parsed
   * it into (`takelight_chain::schema::EraName`, as the plugin's editor reads
   * it in `src/lib/chain.ts`): a decade, the modern era, the classic era, or
   * a record's era — the record's name never translated.
   */
  function era(style) {
    var name = style.eraName;
    if (!name) return style.era;
    switch (name.kind) {
      case 'decade':
        return fillIn(word('decade'), { year: String(name.year) });
      case 'modern':
        return word('modern');
      case 'classic':
        return word('classic');
      default:
        return fillIn(word('record'), { record: name.record });
    }
  }

  function years(style) {
    return style.from === style.to ? String(style.from) : style.from + '–' + style.to;
  }

  function start() {
    var rows = document.getElementById('roster-rows');
    var shown = document.getElementById('roster-shown');
    var box = document.getElementById('roster-q');
    if (rows === null || shown === null || box === null) return;

    var styles = [];
    var chains = 0;
    var loaded = false;
    var failure = null;
    var wantKind = '';
    var pending = 0;

    function message(text) {
      rows.textContent = '';
      var tr = document.createElement('tr');
      var td = document.createElement('td');
      td.colSpan = 5;
      td.textContent = text;
      tr.appendChild(td);
      rows.appendChild(tr);
    }

    function cell(tr, text) {
      var td = document.createElement('td');
      td.textContent = text;
      tr.appendChild(td);
    }

    function row(style) {
      var tr = document.createElement('tr');
      cell(tr, style.name);
      cell(tr, word(style.kind) || style.kind);
      cell(tr, era(style) + ' (' + years(style) + ')');
      cell(
        tr,
        style.roles
          .map(function (role) {
            return word(role) || role;
          })
          .join(', '),
      );
      cell(tr, style.genre);
      return tr;
    }

    /** The numbers at the top: chains, and the artists and genres they are for. */
    function counts() {
      var subjects = { artist: {}, genre: {} };
      for (var i = 0; i < styles.length; i += 1) {
        var kind = subjects[styles[i].kind];
        if (kind !== undefined) kind[styles[i].name] = true;
      }
      var by = {
        chains: chains,
        artist: Object.keys(subjects.artist).length,
        genre: Object.keys(subjects.genre).length,
      };
      var nodes = document.querySelectorAll('[data-roster-count]');
      for (var n = 0; n < nodes.length; n += 1) {
        var value = by[nodes[n].getAttribute('data-roster-count')];
        if (value !== undefined) nodes[n].textContent = number(value);
      }
    }

    /*
     * ⛔⛔ EVERY STYLE IS DRAWN, A–Z, in chunks, one per frame, so the first
     * screen is cheap and the list is still complete (MIDI Master's roster once
     * stopped at 300 rows and nobody could tell).
     */
    function draw() {
      pending += 1;
      var drawing = pending;
      if (failure !== null) {
        message(word(failure));
        shown.textContent = '';
        return;
      }
      if (!loaded) return;
      counts();
      var needle = box.value.trim().toLowerCase();
      var matched = styles.filter(function (s) {
        if (wantKind && s.kind !== wantKind) return false;
        // the English era and the one on the page both find it
        return needle === '' || (s.hay + ' ' + era(s).toLowerCase()).indexOf(needle) !== -1;
      });
      shown.textContent = fillIn(word('shown'), {
        shown: number(matched.length),
        total: number(styles.length),
      });
      if (matched.length === 0) {
        message(word('none'));
        return;
      }
      rows.textContent = '';
      var at = 0;
      function more() {
        if (drawing !== pending) return;
        var batch = document.createDocumentFragment();
        var until = Math.min(at + CHUNK, matched.length);
        for (; at < until; at += 1) batch.appendChild(row(matched[at]));
        rows.appendChild(batch);
        if (at < matched.length) window.requestAnimationFrame(more);
      }
      more();
    }

    /** The row of kinds: one is always pressed. */
    var buttons = document.querySelectorAll('[data-roster-kind]');
    for (var i = 0; i < buttons.length; i += 1) {
      buttons[i].addEventListener('click', function (event) {
        var chosen = event.currentTarget;
        for (var j = 0; j < buttons.length; j += 1) {
          var on = buttons[j] === chosen;
          buttons[j].setAttribute('aria-pressed', on ? 'true' : 'false');
          buttons[j].classList.toggle('btn-primary', on);
          buttons[j].classList.toggle('btn-secondary', !on);
        }
        wantKind = chosen.getAttribute('data-roster-kind');
        draw();
      });
    }
    box.addEventListener('input', draw);

    // The kit sets <html lang> as it paints a language: redraw in its words.
    if (typeof window.MutationObserver === 'function') {
      new window.MutationObserver(draw).observe(document.documentElement, {
        attributes: true,
        attributeFilter: ['lang'],
      });
    }

    /*
     * ⛔ `no-store`, because a cached roster is a roster that lies. ⚠ From a
     * `file://` page the browser refuses the request, and the reader is told
     * so rather than shown an empty table.
     */
    if (location.protocol === 'file:') {
      failure = 'file';
      draw();
      return;
    }
    fetch('roster.json', { cache: 'no-store' })
      .then(function (response) {
        if (!response.ok) throw new Error(String(response.status));
        return response.json();
      })
      .then(function (data) {
        // ⚠ Written by `tlc build`, held to its shape by `tlc build --check`
        // and the site's tests: no guard against another shape.
        styles = data.styles;
        chains = data.chains;
        // ⚠ The search haystack, built once rather than on every keystroke.
        styles.forEach(function (s) {
          s.hay = (s.name + ' ' + s.era + ' ' + years(s) + ' ' + s.genre).toLowerCase();
        });
        loaded = true;
        draw();
      })
      .catch(function () {
        failure = 'failed';
        draw();
      });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', start);
  } else {
    start();
  }
})();
